<script setup>
import SidePanel from '../Components/SynauxSidePanel.vue';
import { computed, ref } from 'vue';
import { useForm, usePage } from '@inertiajs/vue3';
import B from '../Components/SynauxButton.vue';
import F from '../Components/SynauxField.vue';
import T from '../Components/SynauxTitle.vue';
import S from '../Components/SynauxStatus.vue';
import E from '../Components/SynauxEmpty.vue';
import RequestForm from '../Components/SynauxRequestForm.vue';
import ClientScreens from './ClientScreens.vue';
import { money, date, initials, useSubmit } from '../support/synaux';
// El muro y el directorio solo usan información pública; invitaciones y propuestas llegan autorizadas.
const props = defineProps({ data: Object });
const page = usePage();
const submit = useSubmit();
const query = ref('');
const category = ref('Todas');
const skill = ref('');
const order = ref('recent');
const skills = computed(()=>['Todas',...new Set((props.data.professionals ?? []).flatMap(p=>p.skills))]);
const compare = ref(props.data.referenceKey === 'comparar-propuestas');
const modal = ref(props.data.referenceKey === 'propuesta-formulario' ? 'proposal' : '');
const selected = computed(() => props.data.selected ?? {});
const professional = computed(() => props.data.screen === 'profesional');
const section = computed(() => props.data.screen === 'cliente' ? ({publicaciones:'publicaciones',propuestas:'propuestas',invitaciones:'invitaciones'}[props.data.section]) : professional.value ? props.data.section || 'resumen' : props.data.screen);
const ownId = computed(() => page.props.auth?.id ?? (props.data.area === 'profesional' ? 2 : 1));
const proposals = computed(() => (props.data.proposals ?? []).filter(p => props.data.preview || (professional.value ? p.professional_user_id === ownId.value : p.owner_id === ownId.value)));
const invitations = computed(() => (props.data.invitations ?? []).filter(p => props.data.preview || (professional.value ? p.professional_user_id === ownId.value : p.owner_id === ownId.value)));
const requests = computed(() => (props.data.requests ?? []).filter(r => r.visibility === 'public'));
const opportunities = computed(() => (props.data.opportunities ?? []).filter(r => (category.value === 'Todas' || r.category === category.value) && `${r.title} ${r.description} ${r.skills.join(' ')}`.toLowerCase().includes(query.value.toLowerCase())).sort((a,b) => order.value === 'proposals' ? b.proposal_count-a.proposal_count : new Date(b.published_at)-new Date(a.published_at)));
const professionals = computed(() => (props.data.professionals ?? []).filter(p => (!skill.value || skill.value === 'Todas' || p.skills.includes(skill.value)) && `${p.name} ${p.headline} ${p.skills.join(' ')}`.toLowerCase().includes(query.value.toLowerCase())));
const categories = computed(() => ['Todas',...new Set((props.data.opportunities ?? []).map(r => r.category).filter(Boolean))]);
const proposalForm = useForm({request_id:selected.value.id,message:'',estimated_delivery_days:30,amount:'',currency_code:'ARS'});
const invitationForm = useForm({request_id:'',professional_id:selected.value.id});
const profile = props.data.profile;
const profileForm = useForm({brand_name:profile?.brand_name ?? '',headline:profile?.headline ?? '',bio:profile?.bio ?? '',location:profile?.location ?? '',skills:profile?.skills?.join(', ') ?? '',availability_status:profile?.availability_status ?? 'available',active:profile?.active ?? true});
function act(action,values) { submit(useForm(values),action); }
function invite() { submit(invitationForm,'invitacion',{previewTarget:'invitaciones-enviadas'}); }
function propose() { submit(proposalForm,'propuesta',{previewTarget:'mis-propuestas'}); }
</script>
<template>
    <!-- Búsquedas reactivas, estados vacíos y carga reproducen los cuatro estados del muro. -->
    <section v-if="section === 'muro'" class="page shell"><T eyebrow="Conectamos proyectos y talento" title="Proyectos que buscan talento digital" description="Explorá necesidades publicadas por clientes. Solo se muestran datos públicos; la información de contacto permanece privada."><B href="/solicitudes/nueva" arrow>Publicar solicitud</B></T><div class="filters wall-filters"><F v-model="query" label="Buscar oportunidades" placeholder="Proyecto, habilidad o palabra clave" /><F v-model="category" label="Categoría" type="select" :options="categories" /><F v-model="order" label="Ordenar por" type="select" :options="[{value:'recent',label:'Más recientes'},{value:'proposals',label:'Más propuestas'}]" /></div><div class="notice"><p>Las publicaciones son solicitudes de proyectos. Una propuesta no reemplaza el presupuesto formal ni confirma una contratación.</p></div><div v-if="data.referenceKey === 'muro-cargando'" class="opportunity-grid" role="status" aria-label="Cargando oportunidades"><v-card v-for="n in 3" :key="n" class="card skeleton-card"><div class="skeleton" /><div class="skeleton" /><div class="skeleton" /></v-card></div><div v-else-if="opportunities.length && !['muro-vacio','muro-sin-resultados'].includes(data.referenceKey)" class="opportunity-grid"><v-card v-for="r in opportunities" :key="r.id" class="card opportunity-card"><div class="section-head"><span class="eyebrow">{{ r.category }}</span><S :status="r.status" /></div><h2>{{ r.title }}</h2><p>{{ r.description }}</p><div class="tags"><span v-for="tag in r.skills" :key="tag">{{ tag }}</span></div><dl class="data-list"><div><dt>Referencia</dt><dd>{{ r.budget_reference || 'A definir' }}</dd></div><div><dt>Plazo</dt><dd>{{ r.desired_deadline || 'A coordinar' }}</dd></div></dl><div class="section-head"><small>{{ date(r.published_at) }} · {{ r.proposal_count }} propuestas</small><B :href="`/oportunidades/${r.id}`" variant="ghost" arrow>Ver oportunidad</B></div></v-card></div><E v-else :title="query || category !== 'Todas' || data.referenceKey === 'muro-sin-resultados' ? 'No encontramos oportunidades con esos filtros' : 'Todavía no hay oportunidades publicadas'" text="Probá una nueva búsqueda o volvé más adelante."><B variant="secondary" @click="query = ''; category = 'Todas'">Limpiar filtros</B></E></section>
    <section v-else-if="section === 'oportunidad'" class="page shell"><B href="/oportunidades" variant="ghost">← Volver al muro</B><T :eyebrow="`${selected.category} · SOL-${selected.id}`" :title="selected.title"><S :status="selected.status" /></T><div class="detail-layout"><v-card class="card"><h2>Sobre el proyecto</h2><p class="preserve-lines">{{ selected.description }}</p><h3>Habilidades buscadas</h3><div class="tags"><span v-for="tag in selected.skills" :key="tag">{{ tag }}</span></div><dl class="data-list"><div><dt>Servicio</dt><dd>{{ selected.service_name }}</dd></div><div><dt>Publicado</dt><dd>{{ date(selected.published_at) }}</dd></div></dl></v-card><aside><v-card class="card"><p class="eyebrow">Información de la solicitud</p><dl class="data-list"><div><dt>Presupuesto de referencia</dt><dd>{{ selected.budget_reference || 'A definir' }}</dd></div><div><dt>Plazo deseado</dt><dd>{{ selected.desired_deadline || 'A coordinar' }}</dd></div></dl><template v-if="$page.props.auth || data.preview"><B v-if="selected.is_owner" :href="`/solicitudes/${selected.id}`">Administrar solicitud</B><B v-else-if="data.existingProposal" href="/profesional/propuestas" variant="secondary">Ver mi propuesta</B><B v-else-if="data.profile?.active || data.preview" :disabled="selected.status !== 'open'" @click="modal = 'proposal'">Presentar propuesta</B><B v-else href="/profesional/perfil">Completar perfil profesional</B></template><B v-else href="/ingresar">Ingresar para postularme</B><p class="reference-note">La selección abre la preparación de un presupuesto. No implica contratación automática.</p></v-card></aside></div></section>
    <!-- El directorio muestra el perfil público y permite invitar a una solicitud propia abierta. -->
    <section v-else-if="section === 'profesionales'" class="page shell"><T eyebrow="Directorio profesional" title="Encontrá el perfil indicado" description="Explorá especialidades y trabajos. También podés invitar a una solicitud sin compartir datos privados." /><div class="filters"><F v-model="query" label="Buscar profesional o habilidad" placeholder="Ej. Vue, diseño, identidad" /><F v-model="skill" label="Habilidad" type="select" :options="skills" /></div><div class="professional-grid"><v-card v-for="p in professionals" :key="p.id" class="card professional-card"><div class="avatar">{{ initials(p.name) }}</div><h2>{{ p.name }}</h2><p class="professional-headline">{{ p.headline }}</p><S :status="p.availability_status" /><p>{{ p.bio }}</p><div class="tags"><span v-for="tag in p.skills" :key="tag">{{ tag }}</span></div><B :href="`/profesionales/${p.id}`" variant="secondary" arrow>Ver perfil</B></v-card></div><E v-if="!professionals.length" title="No encontramos profesionales" text="Los perfiles publicados aparecerán en este directorio." /></section>
    <section v-else-if="section === 'perfil-profesional'" class="page shell"><B href="/profesionales" variant="ghost">← Volver al directorio</B><div class="profile-hero"><div class="avatar large">{{ initials(selected.name) }}</div><div><p class="eyebrow">Perfil profesional</p><h1>{{ selected.name }}</h1><p class="lead">{{ selected.headline }}</p><S :status="selected.availability_status" /><p>{{ selected.location }}</p></div></div><div class="detail-layout"><div class="stack"><v-card class="card"><h2>Acerca de mí</h2><p class="preserve-lines">{{ selected.bio }}</p><h3>Habilidades</h3><div class="tags"><span v-for="tag in selected.skills" :key="tag">{{ tag }}</span></div></v-card><v-card class="card"><h2>Trabajos destacados</h2><div class="portfolio-grid"><a v-for="w in data.works" :key="w.id" :href="data.preview ? '/prototipo/trabajo' : `/trabajos/${w.id}`" class="work-card"><img v-if="w.cover_path" :src="w.cover_path" :alt="w.title"><h3>{{ w.title }}</h3></a></div><p v-if="!data.works?.length">Todavía no hay trabajos públicos.</p></v-card></div><aside><v-card class="card"><h3>¿Trabajamos juntos?</h3><p>Invitá a este profesional a una de tus solicitudes abiertas.</p><template v-if="$page.props.auth || data.preview"><B v-if="data.requests?.some(r => r.status === 'open')" @click="modal = 'invite'">Invitar a una solicitud</B><B v-else href="/solicitudes/nueva">Crear solicitud</B></template><B v-else href="/ingresar">Ingresar para invitar</B></v-card></aside></div></section>
    <section v-else-if="section === 'publicar'" class="page shell"><T eyebrow="Estimación y solicitud" title="Prepará tu proyecto" description="Elegí los servicios, revisá la referencia de precio y completá tu pedido. Podés comenzar sin registrarte." /><RequestForm :data="data" /></section>
    <!-- Los espacios de cliente y profesional usan colecciones distintas para propuestas e invitaciones. -->
    <section v-else-if="professional && section === 'resumen'" class="page shell"><T eyebrow="Área profesional" :title="`Hola, ${data.profile?.brand_name ?? $page.props.auth?.name ?? 'profesional'}`" description="Encontrá oportunidades y seguí las conversaciones que pueden convertirse en proyectos."><B href="/oportunidades" arrow>Explorar oportunidades</B></T><div class="stats-grid"><v-card v-for="[label,value] in [['Propuestas enviadas',proposals.length],['Invitaciones',invitations.filter(i=>i.status==='pending').length],['Presupuestos',data.quotes?.length ?? 0],['Proyectos',data.projects?.length ?? 0]]" :key="label" class="card stat"><span>{{ label }}</span><strong>{{ value }}</strong></v-card></div><div class="detail-layout"><v-card class="card"><h2>Tus últimas propuestas</h2><div v-for="p in proposals.slice(0,3)" :key="p.id" class="list-row"><div><h3>{{ p.title }}</h3><S :status="p.status" /></div><B :href="`/oportunidades/${p.project_request_id}`" variant="secondary">Ver solicitud</B></div><E v-if="!proposals.length" title="Tu próximo proyecto empieza acá" text="Explorá el muro y presentá una propuesta acorde a tu experiencia." /></v-card><aside><v-card class="card soft-panel"><h3>Tu perfil profesional</h3><p>Mantené actualizadas tus habilidades y disponibilidad.</p><B href="/profesional/perfil" variant="secondary">Editar mi perfil</B><B href="/profesional/portfolio" variant="ghost">Administrar portfolio</B></v-card></aside></div></section>
    <section v-else-if="section === 'perfil' && professional" class="page shell narrow"><T eyebrow="Área profesional" title="Mi perfil profesional" description="Esta información se muestra en el directorio cuando tu perfil está visible." /><v-card class="card form-card"><form @submit.prevent="submit(profileForm,'perfil')"><div class="form-grid"><F v-model="profileForm.brand_name" label="Nombre profesional o marca" required /><F v-model="profileForm.headline" label="Especialidad / titular" required /></div><F v-model="profileForm.bio" type="textarea" label="Acerca de mí" required /><F v-model="profileForm.skills" label="Habilidades (separadas por comas)" /><div class="form-grid"><F v-model="profileForm.location" label="Ubicación" /><F v-model="profileForm.availability_status" type="select" label="Disponibilidad" :options="[{value:'available',label:'Disponible'},{value:'busy',label:'Con agenda'},{value:'unavailable',label:'No disponible'}]" /></div><label class="select-row"><input v-model="profileForm.active" type="checkbox">Mostrar mi perfil en el directorio</label><div class="form-actions"><B href="/profesional" variant="secondary">Volver</B><B type="submit" :disabled="profileForm.processing">Guardar perfil</B></div></form></v-card></section>
    <section v-else-if="section === 'publicaciones'" class="page shell"><T eyebrow="Área cliente" title="Mis publicaciones" description="Administrá tus solicitudes públicas y las propuestas recibidas."><B href="/solicitudes/nueva" arrow>Publicar solicitud</B></T><div class="stack"><v-card v-for="r in requests" :key="r.id" class="card list-row"><div><small>SOL-{{ r.id }} · {{ date(r.created_at) }}</small><h3>{{ r.title }}</h3><S :status="r.status" /><p>{{ r.proposal_count }} propuestas recibidas</p></div><div class="button-row"><B :href="`/solicitudes/${r.id}`" variant="secondary">Ver detalle</B><B href="/cliente/propuestas">Ver propuestas</B></div></v-card></div><E v-if="!requests.length" title="Todavía no publicaste solicitudes" text="Publicá una necesidad para recibir propuestas de profesionales." href="/solicitudes/nueva" action="Crear publicación" /></section>
    <section v-else-if="section === 'propuestas'" class="page shell"><T :eyebrow="professional ? 'Área profesional' : 'Área cliente'" :title="professional ? 'Mis propuestas' : compare ? 'Comparar propuestas' : 'Propuestas recibidas'" description="La propuesta presenta un enfoque inicial. La contratación se confirma con un presupuesto formal."><B v-if="!professional && proposals.length" variant="secondary" @click="compare = !compare">{{ compare ? 'Ver listado' : 'Comparar propuestas' }}</B><B v-if="professional" href="/oportunidades" arrow>Ver oportunidades</B></T><div :class="compare ? 'compare-grid' : 'stack'"><v-card v-for="p in proposals" :key="p.id" class="card"><div class="section-head"><div><p class="eyebrow">{{ p.title }}</p><h2>{{ professional ? 'Tu propuesta' : p.name }}</h2></div><S :status="p.status" /></div><p>{{ p.headline }}</p><p class="preserve-lines">{{ p.message }}</p><div class="tags"><span v-for="tag in p.skills" :key="tag">{{ tag }}</span></div><dl class="data-list"><div><dt>Referencia económica</dt><dd>{{ money(p.amount,p.currency_code) }}</dd></div><div><dt>Plazo estimado</dt><dd>{{ p.estimated_delivery_days }} días</dd></div><div><dt>Fecha</dt><dd>{{ date(p.created_at) }}</dd></div></dl><div class="button-row"><B :href="`/profesionales/${p.professional_profile_id}`" variant="secondary">Ver perfil</B><B v-if="professional && p.status === 'submitted'" variant="ghost" @click="act('retirar-propuesta',{id:p.id})">Retirar propuesta</B><B v-else-if="!professional && p.status === 'submitted'" @click="act('seleccionar-propuesta',{id:p.id})">Elegir para presupuestar</B><B v-if="professional && p.status === 'accepted'" :href="`/editor/presupuesto?solicitud=${p.project_request_id}`">Preparar presupuesto</B></div></v-card></div><E v-if="!proposals.length" :title="professional ? 'Todavía no enviaste propuestas' : 'Todavía no recibiste propuestas'" text="Las propuestas van a aparecer acá con sus estados." :href="professional ? '/oportunidades' : '/cliente/publicaciones'" action="Ver oportunidades" /></section>
    <section v-else-if="section === 'invitaciones'" class="page shell"><T :eyebrow="professional ? 'Área profesional' : 'Área cliente'" :title="professional ? 'Invitaciones recibidas' : 'Invitaciones enviadas'" description="Seguí el estado de las invitaciones a colaborar en un proyecto." /><div class="stack"><v-card v-for="i in invitations" :key="i.id" class="card list-row"><div><small>{{ date(i.created_at) }}</small><h3>{{ i.title }}</h3><p>{{ professional ? 'Te invitaron a presentar una propuesta' : i.name }}</p><S :status="i.status" /></div><div class="button-row"><template v-if="professional && i.status === 'pending' && i.request_status === 'open'"><B variant="secondary" @click="act('responder-invitacion',{id:i.id,status:'declined'})">Declinar</B><B @click="act('responder-invitacion',{id:i.id,status:'accepted'})">Aceptar invitación</B></template><B v-else-if="professional && i.status === 'accepted'" :href="`/oportunidades/${i.project_request_id}`" variant="secondary">Ver solicitud</B><B v-else-if="!professional" :href="`/profesionales/${i.professional_profile_id}`" variant="secondary">Ver profesional</B></div></v-card></div><E v-if="!invitations.length" title="Todavía no hay invitaciones" text="Cuando haya invitaciones, vas a poder seguir su estado desde acá." /></section>
    <ClientScreens v-else-if="['presupuestos','proyectos'].includes(section)" :data="{...data,screen:'cliente',section}" />
    <!-- Los formularios modales conservan los datos si el servidor devuelve errores. -->
    <SidePanel title="Propuestas e invitaciones" :persistent="proposalForm.processing || invitationForm.processing" :model-value="!!modal" max-width="520" @update:model-value="modal = $event ? modal : ''"><div class="synaux-app"><v-card class="card modal-card"><template v-if="modal === 'proposal'"><p class="eyebrow">{{ selected.title }}</p><h2>Presentar propuesta</h2><p>Contá cómo abordarías el proyecto. Los importes son una referencia inicial.</p><form @submit.prevent="propose"><F v-model="proposalForm.message" label="Tu enfoque y experiencia" type="textarea" required /><div class="form-grid"><F v-model="proposalForm.estimated_delivery_days" label="Plazo estimado (días)" type="number" min="1" required /><F v-model="proposalForm.amount" label="Importe de referencia (opcional)" type="number" min="0" step="0.01" /></div><F v-model="proposalForm.currency_code" label="Moneda" type="select" :options="['ARS','USD','EUR']" /><div class="form-actions"><B variant="secondary" :disabled="proposalForm.processing || invitationForm.processing" @click="modal = ''">Cancelar</B><B type="submit" :disabled="proposalForm.processing">Enviar propuesta</B></div></form></template><template v-else><h2>Invitar a {{ selected.name }}</h2><form @submit.prevent="invite"><F v-model="invitationForm.request_id" type="select" label="Elegí una solicitud" required :options="data.requests?.filter(r=>r.status==='open').map(r=>({value:r.id,label:r.title}))" /><div class="form-actions"><B variant="secondary" :disabled="proposalForm.processing || invitationForm.processing" @click="modal = ''">Cancelar</B><B type="submit" :disabled="invitationForm.processing">Enviar invitación</B></div></form></template></v-card></div></SidePanel>
</template>


